const CG = { el: null, game: null, bet: 100, msg: "", cls: "", crash: { st: "idle", m: 1, at: 0, t: 0, hist: [], path: [], B: [{ amt: 100, on: true, st: "idle", cm: 0, win: 0 }, { amt: 100, on: false, st: "idle", cm: 0, win: 0 }] }, mines: { st: "idle", bombs: 3, cells: [], found: 0 }, rad: { ang: 0, spin: null, hist: [] }, models: [] };
const CG_CHIPS = [[10, "#2a64d6", "#ffffff", "10"], [100, "#c21d2b", "#ffffff", "100"], [1000, "#17181c", "#d4a640", "1K"], [10000, "#6a2bb0", "#f2d36b", "10K"]];
const cgFmt = n => (typeof kontoFmt === "function" ? kontoFmt(n) : n + " $");
