  for (const sx of [-1, 1]) { const st = new THREE.Mesh(new THREE.BoxGeometry(0.1, Y + 0.2, 0.12), sw); st.position.set(sx * 0.55, (Y + 0.2) / 2 + 0.2, 0.18); st.rotation.z = sx * -0.25; g.add(st); }
