  schild.position.set(0, 0.42, -0.0); schild.rotation.y = Math.PI; g.add(schild); { const sb = new THREE.Mesh(new THREE.BoxGeometry(1.25, 0.32, 0.06), sw); sb.position.set(0, 0.42, 0.035); g.add(sb); }
