CG.plinko = { balls: [], last: [] }; CG.hilo = { st: "idle", card: 7, suit: "♠", m: 1, n: 0, bet: 0, hist: [] };
function plinkoWurf() { const P = CG.plinko; if (P.balls.length >= 6) return; if (!cgPay(CG.bet)) return; const weg = []; for (let r = 0; r < PLINKO_N; r++) weg.push(Math.random() < 0.5 ? 0 : 1);
  P.balls.push({ weg, t: 0, bet: CG.bet, fach: weg.reduce((a, b) => a + b, 0) }); CG.msg = ""; if (P.balls.length === 1) { cgRender(); plinkoLoop(); } }
function plinkoLoop() { const P = CG.plinko; if (!P.balls.length || !cgIsOpen()) return; const now = performance.now(); P.prev = P.prev || now; const dt = Math.min(0.05, (now - P.prev) / 1000); P.prev = now;
  for (const b of [...P.balls]) { b.t += dt * 7.5; if (b.t >= PLINKO_N + 1) { const m = PLINKO_M[b.fach], win = Math.floor(b.bet * m); if (win) jetGive(win); P.last.push(m); P.balls.splice(P.balls.indexOf(b), 1); CG.msg = m + "× – " + (win >= b.bet ? "+" + cgFmt(win - b.bet) : "zurück " + cgFmt(win)); CG.cls = win >= b.bet ? "ok" : ""; cgRender(); } }
  plinkoDraw(); if (P.balls.length) requestAnimationFrame(plinkoLoop); else P.prev = 0; }
function plinkoDraw(c, w, h) { if (!c) { const cv = CG.el && CG.el.querySelector("canvas"); if (!cv) return; c = cv.getContext("2d"); w = cv.width; h = cv.height; } const P = CG.plinko, dx = 40, dy = 24, x0 = w / 2, y0 = 30;
  c.fillStyle = "#120a22"; c.fillRect(0, 0, w, h); c.fillStyle = "#e8e0ff"; for (let r = 0; r < PLINKO_N; r++) for (let k = 0; k <= r + 2; k++) { c.beginPath(); c.arc(x0 + (k - (r + 2) / 2) * dx, y0 + r * dy, 3.5, 0, 7); c.fill(); }
  const fy = y0 + PLINKO_N * dy + 4; PLINKO_M.forEach((m, i) => { const x = x0 + (i - 6) * dx; c.fillStyle = m >= 5 ? "#ff3b5c" : m >= 2 ? "#ff7a2e" : m >= 1 ? "#ffb02e" : "#3a9a5a"; c.fillRect(x - dx / 2 + 2, fy, dx - 4, 26); c.fillStyle = "#111"; c.font = "800 12px system-ui"; c.textAlign = "center"; c.fillText(m + "×", x, fy + 17); });
  for (const b of P.balls) { const r = Math.min(PLINKO_N, Math.floor(b.t)), f = b.t - r, k0 = b.weg.slice(0, r).reduce((a, q) => a + q, 0), k1 = r < PLINKO_N ? k0 + b.weg[r] : k0, kx = k0 + (k1 - k0) * f, x = x0 + (kx - r / 2 - f / 2) * dx + (r < PLINKO_N ? 0 : 0), y = y0 - 14 + (r + f) * dy - Math.sin(f * Math.PI) * 8;
    c.fillStyle = "#fff"; c.shadowColor = "#f2d36b"; c.shadowBlur = 10; c.beginPath(); c.arc(x, Math.min(y, fy + 8), 7, 0, 7); c.fill(); c.shadowBlur = 0; }
  c.fillStyle = "#bfb497"; c.font = "12px system-ui"; c.textAlign = "left"; c.fillText("Letzte: " + P.last.slice(-8).map(m => m + "×").join("  "), 10, h - 6); }
const hiloP = (v, d) => d > 0 ? (14 - v) / 13 : v / 13;
