function hiloStart() { const H = CG.hilo; if (!cgPay(CG.bet)) return; const k = hiloKarte(); Object.assign(H, { st: "play", card: k.v, suit: k.f, m: 1, n: 0, bet: CG.bet, hist: [k.v] }); CG.msg = "Höher oder tiefer?"; CG.cls = ""; cgRender(); }
