// ---- Craps (Nicolas 2026-11-19 "Ja, weiter"; Craps-Tisch im realistischen Casino): Pass Line, Don't Pass, Field mit Jetons (Chip waehlen, Feld anklicken). Come-out: Pass gewinnt 7/11, verliert 2/3/12;
// Don't Pass umgekehrt, 12 = unentschieden. Sonst wird die Zahl zum Punkt: Pass gewinnt, wenn der Punkt vor der 7 faellt, Don't Pass bei 7 vor dem Punkt (1:1). Field gilt fuer einen Wurf:
// 3/4/9/10/11 1:1, 2 zahlt 2:1, 12 zahlt 3:1, sonst verloren. Solange ein Punkt steht, bleibt das Fenster offen (Einsaetze liegen). Wuerfel rollen 0,8 s.
CG.craps = { bets: { pass: 0, dont: 0, field: 0 }, point: 0, d: [3, 4], roll: false, verlauf: [] };
function crapsSetzen(id) { const K = CG.craps; if (K.roll || ((id === "pass" || id === "dont") && K.point)) return; if (!cgPay(CG.bet)) return; K.bets[id] += CG.bet; CG.msg = ""; cgRender(); }
function crapsZurueck() { const K = CG.craps; if (K.roll || K.point) return; let n = 0; for (const k in K.bets) { n += K.bets[k]; K.bets[k] = 0; } if (n) jetGive(n); CG.msg = n ? cgFmt(n) + " zurück" : ""; cgRender(); }
function crapsWurf() { const K = CG.craps; if (K.roll || !Object.values(K.bets).some(Boolean)) return; K.roll = true; let n = 0; const tick = () => { K.d = [1 + Math.floor(Math.random() * 6), 1 + Math.floor(Math.random() * 6)]; cgRender(); if (++n < 8) setTimeout(tick, 100); else { K.roll = false; crapsAus(); } }; tick(); }
function crapsAus() { const K = CG.craps, b = K.bets, s = K.d[0] + K.d[1], t = []; let gew = 0; const zahl = (v, txt) => { gew += v; t.push(txt); };
  if (b.field) { const f = s === 2 ? 3 : s === 12 ? 4 : [3, 4, 9, 10, 11].includes(s) ? 2 : 0; if (f) zahl(b.field * f, "Field +" + cgFmt(b.field * (f - 1))); else t.push("Field verloren"); b.field = 0; }
  if (!K.point) { if (s === 7 || s === 11) { if (b.pass) zahl(b.pass * 2, "Pass +" + cgFmt(b.pass)); if (b.dont) t.push("Don't Pass verloren"); b.pass = b.dont = 0; }
    else if (s === 2 || s === 3 || s === 12) { if (b.pass) t.push("Pass verloren"); if (b.dont) { if (s === 12) zahl(b.dont, "Don't Pass: 12 unentschieden"); else zahl(b.dont * 2, "Don't Pass +" + cgFmt(b.dont)); } b.pass = b.dont = 0; }
    else if (b.pass || b.dont) { K.point = s; t.push("Punkt ist " + s); } }
  else if (s === K.point) { if (b.pass) zahl(b.pass * 2, "Punkt getroffen – Pass +" + cgFmt(b.pass)); if (b.dont) t.push("Don't Pass verloren"); b.pass = b.dont = 0; K.point = 0; }
  else if (s === 7) { if (b.dont) zahl(b.dont * 2, "Sieben – Don't Pass +" + cgFmt(b.dont)); if (b.pass) t.push("Sieben – Pass verloren"); b.pass = b.dont = 0; K.point = 0; }
  if (gew) jetGive(gew); K.verlauf.push(s); CG.msg = "Wurf " + s + (t.length ? " · " + t.join(" · ") : ""); CG.cls = gew ? "ok" : t.some(x => /verloren/.test(x)) ? "err" : ""; cgRender(); }
