function vpWert(K) { const r = K.map(c => vpRang(c.r)).sort((a, b) => a - b), n = {}; for (const x of r) n[x] = (n[x] || 0) + 1; const z = Object.values(n).sort((a, b) => b - a), fl = K.every(c => c.f === K[0].f);
  const str = z.length === 5 && (r[4] - r[0] === 4 || r.join() === "2,3,4,5,14");
  if (fl && str && r[0] === 10) return "Royal Flush"; if (fl && str) return "Straight Flush"; if (z[0] === 4) return "Vierling"; if (z[0] === 3 && z[1] === 2) return "Full House"; if (fl) return "Flush"; if (str) return "Strasse";
  if (z[0] === 3) return "Drilling"; if (z[0] === 2 && z[1] === 2) return "Zwei Paare"; if (z[0] === 2 && Object.entries(n).some(([v, c]) => c === 2 && +v >= 11)) return "Buben oder besser"; return null; }
function vpDeal() { const V = CG.vp; if (!cgPay(CG.bet)) return; V.deck = []; for (const f of BJ_F) for (const r of BJ_R) V.deck.push({ r, f }); for (let i = V.deck.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [V.deck[i], V.deck[j]] = [V.deck[j], V.deck[i]]; }
  V.k = V.deck.splice(0, 5); V.halt = [false, false, false, false, false]; V.bet = CG.bet; V.st = "deal"; V.hand = vpWert(V.k); CG.msg = V.hand ? "Auf der Hand: " + V.hand + " – halten und tauschen" : "Karten zum Halten anklicken, dann tauschen"; CG.cls = ""; cgRender(); }
