// ---- Keno und Turm im Quick-Games-Automaten (Nicolas 2026-11-20 "weiter", IDEEN-CASINO). Keno: 1-10 Zahlen aus 40 waehlen, 10 werden gezogen, Gewinn nach KENO_TAB[gewaehlt][Treffer]
// (je Anzahl auf ca. 93-96 % abgestimmt, gerechnet). Turm: TW_N = 8 Stockwerke, je 3 Felder mit einer Falle; jedes geschaffte Stockwerk ×TW_F (0,97 / (2/3)), jederzeit auszahlen, Falle = Einsatz weg.
const KENO_TAB = { 1: [0, 3.8], 2: [0, 1.7, 5.2], 3: [0, 0, 4.5, 28], 4: [0, 0, 2.3, 7.8, 62], 5: [0, 0, 1.7, 3.5, 17, 126], 6: [0, 0, 0, 4.1, 12, 61, 407], 7: [0, 0, 0, 2.5, 6.7, 25, 134, 672], 8: [0, 0, 0, 1.5, 4.5, 15, 60, 298, 1193], 9: [0, 0, 0, 1.4, 2.8, 6.9, 28, 111, 554, 2079], 10: [0, 0, 0, 0.9, 2.3, 4.7, 14, 59, 293, 1172, 3516] };
const TW_N = 8, TW_F = 0.97 * 1.5;
CG.quick.keno = { wahl: [], zug: [] }; CG.quick.tw = { st: "idle", stufe: 0, falle: [], offen: {}, bet: 0 };
function kenoWahl(n) { const K = CG.quick.keno; K.zug = []; const i = K.wahl.indexOf(n); if (i >= 0) K.wahl.splice(i, 1); else if (K.wahl.length < 10) K.wahl.push(n); cgRender(); }
function kenoZug() { const K = CG.quick.keno; if (!K.wahl.length) return; if (!cgPay(CG.bet)) return; K.zug = []; while (K.zug.length < 10) { const n = 1 + Math.floor(Math.random() * 40); if (!K.zug.includes(n)) K.zug.push(n); }
  const t = K.wahl.filter(n => K.zug.includes(n)).length, f = (KENO_TAB[K.wahl.length] || [])[t] || 0, win = Math.round(CG.bet * f); if (win) jetGive(win); CG.msg = t + " Treffer" + (win ? " – " + f + "× = " + cgFmt(win) : " – verloren"); CG.cls = win > CG.bet ? "ok" : win ? "" : "err"; cgRender(); }
function towerStart() { const T = CG.quick.tw; if (!cgPay(CG.bet)) return; Object.assign(T, { st: "play", stufe: 0, falle: Array.from({ length: TW_N }, () => Math.floor(Math.random() * 3)), offen: {}, bet: CG.bet }); CG.msg = "Unterstes Stockwerk: ein Feld wählen"; CG.cls = ""; cgRender(); }
function towerFeld(c) { const T = CG.quick.tw; if (T.st !== "play") return; T.offen[T.stufe] = c; if (T.falle[T.stufe] === c) { T.st = "ende"; CG.msg = "Falle! Einsatz verloren"; CG.cls = "err"; return cgRender(); }
  T.stufe++; if (T.stufe >= TW_N) return towerAus(); CG.msg = "Geschafft – " + Math.pow(TW_F, T.stufe).toFixed(2) + "×, weiter oder auszahlen"; CG.cls = "ok"; cgRender(); }
function towerAus() { const T = CG.quick.tw; if (T.st !== "play" || !T.stufe) return; const win = Math.round(T.bet * Math.pow(TW_F, T.stufe)); jetGive(win); T.st = "ende"; CG.msg = "Ausgezahlt " + cgFmt(win) + " nach " + T.stufe + " Stockwerken"; CG.cls = "ok"; cgRender(); }
