// ---- Rubbellos im Quick-Games-Automaten (Nicolas 2026-11-20 "weiter", IDEEN-CASINO): Los zum Einsatz kaufen, 9 Felder unter einer Silberschicht (Canvas), mit gedrueckter Maus freirubbeln
// (je Feld nach ein paar Strichen aufgedeckt) oder "Alles aufdecken". Drei gleiche Betraege = dieser Betrag. LOS_KL: Wahrscheinlichkeit und Faktor (33 % Gewinnchance, im Schnitt 93 % zurueck).
const LOS_KL = [[0.002, 100], [0.008, 25], [0.03, 5], [0.09, 2], [0.2, 1]], LOS_W = [1, 2, 5, 25, 100];
CG.quick.los = { st: "idle", felder: [], gewinn: 0, bet: 0, hits: [], deckel: null };
function losKauf() { const L = CG.quick.los; if (!cgPay(CG.bet)) return; let r = Math.random(), f = 0; for (const [p, x] of LOS_KL) { if (r < p) { f = x; break; } r -= p; }
  const feld = []; if (f) feld.push(f, f, f); const zaehl = {}; for (const v of feld) zaehl[v] = (zaehl[v] || 0) + 1;
  while (feld.length < 9) { const v = LOS_W[Math.floor(Math.random() * LOS_W.length)]; if (v === f || (zaehl[v] || 0) >= 2) continue; zaehl[v] = (zaehl[v] || 0) + 1; feld.push(v); }
  for (let i = feld.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [feld[i], feld[j]] = [feld[j], feld[i]]; }
  Object.assign(L, { st: "play", felder: feld, gewinn: f, bet: CG.bet, hits: new Array(9).fill(0), deckel: null }); CG.msg = ""; CG.cls = ""; cgRender(); }
function losDeckel() { const L = CG.quick.los, cv = CG.el && CG.el.querySelector(".los-rubbel"); if (!cv || L.st !== "play") return; const c = cv.getContext("2d");
  if (L.deckel) { c.putImageData(L.deckel, 0, 0); return; }
  const gr = c.createLinearGradient(0, 0, cv.width, cv.height); gr.addColorStop(0, "#b8bcc4"); gr.addColorStop(0.5, "#e8eaee"); gr.addColorStop(1, "#9aa0a8"); c.fillStyle = gr; c.fillRect(0, 0, cv.width, cv.height);
  c.fillStyle = "rgba(60,60,70,.5)"; c.font = "800 18px Georgia"; c.textAlign = "center"; for (let i = 0; i < 9; i++) c.fillText("★", (i % 3 + 0.5) * cv.width / 3, (Math.floor(i / 3) + 0.5) * cv.height / 3 + 6); }
function losRubbel(e) { const L = CG.quick.los, cv = e.target; if (L.st !== "play" || !(e.buttons & 1)) return; const r = cv.getBoundingClientRect(), x = (e.clientX - r.left) / r.width * cv.width, y = (e.clientY - r.top) / r.height * cv.height, c = cv.getContext("2d");
  c.globalCompositeOperation = "destination-out"; c.beginPath(); c.arc(x, y, 16, 0, 7); c.fill(); c.globalCompositeOperation = "source-over"; L.deckel = c.getImageData(0, 0, cv.width, cv.height);
  const i = Math.min(2, Math.floor(x / cv.width * 3)) + 3 * Math.min(2, Math.floor(y / cv.height * 3)); L.hits[i]++; if (L.hits.every(h => h >= 6)) losEnde(); }
addEventListener("pointermove", e => { if (e.target && e.target.classList && e.target.classList.contains("los-rubbel")) losRubbel(e); });
addEventListener("pointerdown", e => { if (e.target && e.target.classList && e.target.classList.contains("los-rubbel")) losRubbel(e); });
function losEnde() { const L = CG.quick.los; if (L.st !== "play") return; L.st = "ende"; const win = Math.round(L.bet * L.gewinn); if (win) jetGive(win); CG.msg = win ? "Drei gleiche – " + cgFmt(win) + " gewonnen!" : "Leider nichts"; CG.cls = win > L.bet ? "ok" : win ? "" : "err"; cgRender(); }
