// ---- Pferderennen "Gotham Derby" (Nicolas 2026-11-20 "weiter – mach die naechsten Schritte alle", IDEEN-CASINO): 6 Pferde mit Quoten (je Rennen neu, 1,8-16×), Wette auf Sieg.
// Siegchance je Pferd = 0,94 / Quote (normiert, also ca. 94 % Auszahlung); der Sieger wird vor dem Start gezogen, das Rennen (12 s, Canvas) zeigt ihn mit Ueberholmanoevern zuerst im Ziel.
const DERBY_N = ["Midnight Rider", "Gotham Thunder", "Silver Gargoyle", "Crimson Bat", "Arkham Ghost", "Wayne Star", "Narrows Flash", "Bristol Belle", "Ace Chemical", "Iceberg Lady"], DERBY_C = ["#e23a3a", "#2a6ad6", "#f2d36b", "#2fb35a", "#b04ad6", "#f08a24"];
CG.derby = { st: "idle", pf: [], wahl: null, sieger: -1, t: 0, ziel: [], bet: 0, hist: [] };
function derbyNeu() { const D = CG.derby, namen = [...DERBY_N].sort(() => Math.random() - 0.5).slice(0, 6), roh = namen.map(() => 0.3 + Math.random() * 1.7), sum = roh.reduce((a, b) => a + b, 0);
  D.pf = namen.map((n, i) => { const pr = roh[i] / sum; return { n, c: DERBY_C[i], p: pr, q: Math.max(1.2, Math.round(0.94 / pr * 10) / 10) }; }); D.wahl = null; }
function derbyStart() { const D = CG.derby; if (D.st === "lauf" || D.wahl === null) return; if (!cgPay(CG.bet)) return; D.bet = CG.bet;
  let r = Math.random() * D.pf.reduce((a, p) => a + 0.94 / p.q, 0); D.sieger = D.pf.findIndex(p => (r -= 0.94 / p.q) < 0); if (D.sieger < 0) D.sieger = 0;
  D.ziel = D.pf.map((_, i) => i === D.sieger ? 11 : 11.3 + Math.random() * 1.6); D.form = D.pf.map(() => [Math.random() * 6, Math.random() * 6, 0.6 + Math.random() * 0.8]); D.t = 0; D.st = "lauf"; CG.msg = "Und sie sind gestartet!"; CG.cls = ""; cgRender(); D.prev = 0; setTimeout(() => derbyLoop(performance.now()), 16); }
function derbyPos(i, t) { const D = CG.derby, T = D.ziel[i], [a, b, k] = D.form[i], u = Math.min(1, t / T); return Math.min(1, u + Math.sin(u * Math.PI) * 0.06 * Math.sin(a + u * 7 * k) + Math.sin(u * Math.PI) * 0.03 * Math.sin(b + u * 13)); }
function derbyLoop(now) { const D = CG.derby; if (D.st !== "lauf" || !cgIsOpen()) { if (D.st === "lauf") derbyEnde(); return; } D.prev = D.prev || now; D.t += Math.min(0.05, (now - D.prev) / 1000); D.prev = now; derbyDraw();
  if (D.t > Math.max(...D.ziel) + 0.4) return derbyEnde(); setTimeout(() => derbyLoop(performance.now()), 16); }
function derbyEnde() { const D = CG.derby; if (D.st !== "lauf") return; D.st = "ende"; D.t = 99; const s = D.pf[D.sieger], win = D.wahl === D.sieger ? Math.round(D.bet * s.q) : 0; if (win) jetGive(win); D.hist.push(D.sieger);
  CG.msg = "Sieger: " + (D.sieger + 1) + " " + s.n + (win ? " – du gewinnst " + cgFmt(win) + "!" : " – deine Wette ist verloren"); CG.cls = win ? "ok" : "err"; const alt = D.pf; derbyNeu(); D.letzte = alt; cgRender(); }
function derbyDraw(c, w, h) { if (!c) { const cv = CG.el && CG.el.querySelector("canvas"); if (!cv) return; c = cv.getContext("2d"); w = cv.width; h = cv.height; } const D = CG.derby, pf = D.st === "lauf" ? D.pf : (D.letzte || D.pf), L = 40, R = w - 40, bh = (h - 40) / 6;
  c.fillStyle = "#1f5a2a"; c.fillRect(0, 0, w, h); for (let i = 0; i < 6; i++) { c.fillStyle = i % 2 ? "#2a6a34" : "#24602e"; c.fillRect(0, 30 + i * bh, w, bh); }
  c.fillStyle = "#fff"; c.fillRect(R, 30, 4, h - 40); c.fillStyle = "#f2d36b"; c.font = "800 14px system-ui"; c.textAlign = "left"; c.fillText(D.st === "lauf" ? "Zeit " + D.t.toFixed(1) + " s" : "Wette auf Sieg wählen", 10, 20);
  pf.forEach((p, i) => { const u = D.st === "lauf" ? derbyPos(i, D.t) : D.st === "ende" || D.letzte ? (i === D.sieger ? 1 : 0.9 + 0.08 * Math.random()) : 0, x = L + (R - L) * u, y = 30 + i * bh + bh / 2;
    c.fillStyle = p.c; c.beginPath(); c.arc(x - 30, y, 9, 0, 7); c.fill(); c.font = "24px system-ui"; c.textAlign = "center"; c.save(); c.translate(x, y + 8); c.scale(-1, 1); c.fillText("🏇", 0, 0); c.restore(); c.fillStyle = "#fff"; c.font = "800 11px system-ui"; c.fillText(String(i + 1), x - 30, y + 4); }); }
derbyNeu();
function buildDerbyAutomat() { const g = buildSpielautomat(0x2a6a34, { screen: cgScreenTex("derby"), sign: "DERBY" }); g.name = "Derby-Automat"; return g; }
