// ---- Lotto "Gotham 6 aus 30" (Nicolas 2026-11-20 "mach die naechsten Schritte alle", IDEEN-CASINO): Reiter LOTTO im Quick-Games-Automaten. 6 Zahlen ankreuzen (oder Quick-Tipp), Schein gilt
// fuer die naechste Ziehung; gezogen wird einmal je Spieltag (LOTTO_DAUER 1200 s = ein Tag-Nacht-Zyklus), die Zahlen kommen aus einem festen Zufall je Ziehungsnummer (fuer alle gleich, auch spaeter
// nachpruefbar). Auswertung alle 15 s und beim Oeffnen; Gewinne aufs Konto (kontoEin) mit Meldung: 3 Richtige 3×, 4: 30×, 5: 700×, 6: 100 000× (ca. 75 % zurueck). Stand in localStorage wm-lotto.
const LOTTO_DAUER = 1200, LOTTO_TAB = { 3: 3, 4: 30, 5: 700, 6: 100000 };
CG.quick.lotto = [];
const lottoZug = () => Math.floor(Date.now() / 1000 / LOTTO_DAUER);
function lottoZahlen(id) { let a = (id * 2654435761) >>> 0; const r = () => { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  const z = []; while (z.length < 6) { const n = 1 + Math.floor(r() * 30); if (!z.includes(n)) z.push(n); } return z.sort((x, y) => x - y); }
function lottoLaden() { try { return JSON.parse(localStorage.getItem("wm-lotto") || "null") || { scheine: [] }; } catch (e) { return { scheine: [] }; } }
function lottoSpeichern(O) { try { localStorage.setItem("wm-lotto", JSON.stringify(O)); } catch (e) {} }
function lottoAbgeben() { const W = CG.quick.lotto; if (W.length !== 6) return; if (!cgPay(CG.bet)) return; const O = lottoLaden(), z = lottoZug() + 1; O.scheine.push({ z, n: [...W].sort((a, b) => a - b), bet: CG.bet }); lottoSpeichern(O);
  CG.msg = "Schein abgegeben für Ziehung Nr. " + z; CG.cls = "ok"; cgRender(); }
function lottoAuswerten() { const O = lottoLaden(), jetzt = lottoZug(); let geaendert = false; const offen = [];
  for (const sc of O.scheine) { if (sc.z > jetzt) { offen.push(sc); continue; } const z = lottoZahlen(sc.z), t = sc.n.filter(n => z.includes(n)).length, f = LOTTO_TAB[t] || 0, win = Math.round(sc.bet * f); geaendert = true;
    if (win && typeof kontoEin === "function") kontoEin(win, "Lotto Ziehung " + sc.z + ": " + t + " Richtige"); if (typeof toast === "function") toast("Lotto-Ziehung " + z.join(" ") + ": " + t + " Richtige" + (win ? " – " + cgFmt(win) + " aufs Konto" : "")); }
  if (geaendert) { O.scheine = offen; lottoSpeichern(O); if (cgIsOpen() && CG.game === "quick" && CG.quick.tab === "lotto") cgRender(); } }
setInterval(lottoAuswerten, 15000); setTimeout(lottoAuswerten, 3000);
