// ---- Bingo (Nicolas 2026-11-20 "mach die naechsten Schritte alle", IDEEN-CASINO): 1-4 Karten je Einsatz (5x5, Spalten B 1-15, I 16-30, N 31-45, G 46-60, O 61-75, Mitte frei);
// 30 Kugeln aus 75 werden nacheinander gezogen (0,35 s), Karten werden automatisch markiert; je Karte volle Reihen (Zeilen, Spalten, Diagonalen): 1 = 5×, 2 = 18×, 3+ = 100×
// (Simulation 60 000 Karten: ca. 94 % zurueck). Automat buildBingoAutomat.
const BINGO_TAB = { 1: 5, 2: 18, 3: 100 };
CG.bingo = { st: "idle", anz: 1, karten: [], zug: [], bet: 0 };
function bingoKarte() { const k = []; for (let c = 0; c < 5; c++) { const sp = []; while (sp.length < 5) { const n = c * 15 + 1 + Math.floor(Math.random() * 15); if (!sp.includes(n)) sp.push(n); } k.push(sp); } return k; }
function bingoLinie(k, zug) { const m = (c, r) => (c === 2 && r === 2) || zug.includes(k[c][r]), z = new Set(); let n = 0; const L = [];
  for (let r = 0; r < 5; r++) L.push([0, 1, 2, 3, 4].map(c => [c, r])); for (let c = 0; c < 5; c++) L.push([0, 1, 2, 3, 4].map(r => [c, r])); L.push([0, 1, 2, 3, 4].map(i => [i, i]), [0, 1, 2, 3, 4].map(i => [i, 4 - i]));
  for (const l of L) if (l.every(([c, r]) => m(c, r))) { n++; for (const [c, r] of l) z.add(c + "," + r); } return { n, zellen: z }; }
function bingoStart() { const G = CG.bingo; if (G.st === "lauf") return; if (!cgPay(CG.bet * G.anz)) return; G.bet = CG.bet; G.karten = Array.from({ length: G.anz }, bingoKarte); G.zug = []; G.st = "lauf"; CG.msg = ""; CG.cls = ""; cgRender();
  const tick = () => { if (G.st !== "lauf") return; let n; do n = 1 + Math.floor(Math.random() * 75); while (G.zug.includes(n)); G.zug.push(n); if (cgIsOpen() && CG.game === "bingo") cgRender(); if (G.zug.length < 30) setTimeout(tick, 350); else bingoEnde(); }; setTimeout(tick, 300); }
function bingoEnde() { const G = CG.bingo; G.st = "ende"; let win = 0; const t = G.karten.map(k => { const n = bingoLinie(k, G.zug).n; win += Math.round(G.bet * (BINGO_TAB[Math.min(3, n)] || 0)); return n; });
  if (win) jetGive(win); CG.msg = "Reihen je Karte: " + t.join(", ") + (win ? " – " + cgFmt(win) + " gewonnen!" : " – leider keine volle Reihe"); CG.cls = win ? "ok" : "err"; if (cgIsOpen()) cgRender(); }
function buildBingoAutomat() { const g = buildSpielautomat(0x8a1a5a, { screen: cgScreenTex("bingo"), sign: "BINGO" }); g.name = "Bingo-Automat"; return g; }
